SERVICES = [
 dict(slug='kantoorschoonmaak', group='schoonmaak', name='Kantoorschoonmaak', headline='Een frisse werkdag. Begint hier.', image='schoonmaak-keuken.webp',
 short='Van werkplekken en vergaderruimtes tot pantry en sanitair. Schoonmaak die meebeweegt met het gebruik van uw kantoor.',
 intro='Een werkplek wordt de hele dag gebruikt. Bij de entree komen bezoekers binnen, in de pantry wordt geluncht en vergaderruimtes wisselen van gezelschap. Die ruimtes hebben niet allemaal dezelfde aandacht nodig. Veele Services verzorgt kantoorschoonmaak in Den Haag en de Randstad, met werkzaamheden en een frequentie die op uw pand worden afgestemd.',
 second='Een bruikbare aanvraag begint daarom bij het dagelijks gebruik van uw kantoor. Hoeveel mensen zijn aanwezig? Zijn er gedeelde werkplekken? En op welke momenten is schoonmaak praktisch? Met die informatie kunnen we bespreken wat regelmatig nodig is en welk onderhoud beter op een apart moment past.',
 scope=[('Werkplekken en gezamenlijke ruimtes','Bespreek de reiniging van werkplekken, vergaderruimtes, looproutes en de entree. Geef aan welke oppervlakken vrij toegankelijk zijn en welke apparatuur of documenten met rust moeten worden gelaten.'),('Pantry, kantine en sanitair','Maak duidelijk welke keukenvoorzieningen, toiletten en wasruimtes onder de opdracht vallen. De bezetting en het gebruik helpen bij het bepalen van een passende frequentie.'),('Periodiek extra aandacht','Naast terugkerende schoonmaak kunt u dieptereiniging, glasbewassing of een schoonmaak rond een verhuizing bespreken. Leg vast welke taken aanvullend zijn, zodat de scope begrijpelijk blijft.')],
 checklist=['Geschatte oppervlakte en aantal verdiepingen','Gebruikte ruimtes en bezetting','Gewenste werkdagen en tijdvensters','Bijzonderheden over toegang en materialen'],
 planning='Begin met een overzicht van de ruimtes. Verdeel de wensen vervolgens in terugkerende werkzaamheden en incidenteel onderhoud. Geef aan wanneer medewerkers of bezoekers aanwezig zijn; de uitvoering kan dan met uw bedrijfsvoering worden besproken.',
 faq=[('Kan schoonmaak buiten kantooruren?','Geef uw gewenste tijden door. We bespreken welke planning mogelijk is, hoe de toegang wordt geregeld en wie het aanspreekpunt is. Een genoemd tijdstip is pas een afspraak na bevestiging.'),('Is een vast aantal vierkante meters nodig?','Een schatting helpt bij de eerste aanvraag. Het type ruimtes, de inrichting en het gebruik zijn ook van belang; alleen de oppervlakte is geen volledige basis voor een voorstel.'),('Kan glasbewassing erbij?','Ja, glasbewassing is apart of in combinatie bespreekbaar. Vermeld binnen- en buitenzijde, het aantal verdiepingen en aandachtspunten over bereikbaarheid.')]),
 dict(slug='vve-schoonmaak', group='schoonmaak', name='VvE-schoonmaak', headline='Samen wonen. Verzorgd binnenkomen.', image='bedrijfsbus.webp',
 short='Een verzorgde entree, een schoon trappenhuis en heldere afspraken voor bestuur, beheerder en bewoners.',
 intro='De gemeenschappelijke ruimtes zijn het visitekaartje van een wooncomplex. Een nette entree en verzorgde gangen zijn prettig voor bewoners en bezoekers. Veele Services biedt schoonmaak voor VvE’s, portieken en flats in Den Haag en de Randstad, afgestemd op het gebouw en de wensen van het bestuur of de beheerder.',
 second='Een portiek met een paar woningen vraagt om andere afspraken dan een complex met meerdere entrees, liften en galerijen. Daarom helpt het om per gebouw vast te leggen wat bij de gezamenlijke ruimtes hoort. Zo kunt u schoonmaak, extra onderhoud en de beschikbare planning gericht bespreken.',
 scope=[('Entrees, portieken en trappen','Vloeren, looproutes en contactpunten zijn logische onderdelen van een schoonmaakplan. Bespreek ook entreedeuren, brievenbussen en de plaatsen waar vuil zich verzamelt.'),('Liften, galerijen en gedeelde ruimtes','Liftcabines, gangen, galerijen, fietsenstallingen en afvalruimtes kunnen worden meegenomen. Leg per ruimte vast welke werkzaamheden en frequentie gewenst zijn.'),('Periodiek onderhoud','Gemeenschappelijke ramen en machinale vloerreiniging kunnen apart in het plan worden opgenomen. Dat maakt onderscheid mogelijk tussen regulier schoonhouden en grotere onderhoudsmomenten.')],
 checklist=['Aantal entrees, verdiepingen en liften','Welke gezamenlijke ruimtes meedoen','Gewenste frequentie en onderhoudsmomenten','Contactpersoon namens bestuur of beheerder'],
 planning='Laat bestuur en beheerder vooraf dezelfde lijst met ruimtes gebruiken. Benoem wat buiten de opdracht valt en hoe aandachtspunten worden doorgegeven. Bij meerdere gebouwen helpt een overzicht per adres om uiteenlopende wensen te voorkomen.',
 faq=[('Kunnen meerdere portieken in één aanvraag?','Ja. Vermeld het aantal gebouwen en de verschillen tussen de portieken. De werkzaamheden, toegang en frequentie kunnen per locatie worden besproken.'),('Valt de binnenkant van woningen hieronder?','VvE-schoonmaak richt zich op afgesproken gemeenschappelijke ruimtes. Een woning is een aparte schoonmaakvraag; vermeld die uitdrukkelijk als u dit wilt combineren.'),('Kunnen glas en vloeren periodiek mee?','Glasbewassing van gezamenlijke ruimtes en periodieke vloerreiniging zijn bespreekbaar naast de reguliere schoonmaak. Geef aan om welke ramen en vloeren het gaat.')]),
 dict(slug='glasbewassing', group='schoonmaak', name='Glasbewassing', headline='Een helder zicht. Een frisse uitstraling.', image='bedrijfsbus-detail.webp',
 short='Glasbewassing voor bedrijfspanden, woningen en VvE’s. De bereikbaarheid van het glas bepaalt mede de aanpak.',
 intro='Schone ramen maken verschil voor de uitstraling van een pand en het uitzicht van binnenuit. Veele Services biedt glasbewassing voor bedrijven, woningen en VvE’s in Den Haag en de Randstad. Een eenmalige schoonmaak of terugkerend onderhoud: beide kunnen worden besproken.',
 second='Voor een goed voorstel is meer nodig dan het aantal ramen. Ook de hoogte, de toegang tot het terrein en de bereikbaarheid van de binnenzijde spelen mee. Vertel daarom welke gevels en verdiepingen het betreft en of er obstakels, bijzondere openingstijden of gebruiksafspraken zijn.',
 scope=[('Bedrijfspanden','Een kantoor of winkel heeft vaak verschillende soorten glas. Geef aan of u alleen buitenramen wilt laten reinigen of ook de binnenzijde, glazen deuren en andere glaspartijen wilt bespreken.'),('Woningen en wooncomplexen','Maak voor een VvE onderscheid tussen gezamenlijke glaspartijen en ramen van individuele woningen. Zo is vooraf duidelijk voor welk deel de aanvraag wordt gedaan.'),('De methode bij uw gebouw','Veele Services noemt traditionele glasreiniging en telescopische reiniging met osmosewater. Welke aanpak geschikt is, hangt af van de situatie en moet voor uw pand worden beoordeeld.')],
 checklist=['Type pand en aantal verdiepingen','Binnenzijde, buitenzijde of beide','Bereikbaarheid en eventuele obstakels','Eenmalige of terugkerende glasbewassing'],
 planning='Spreek af welke glaspartijen worden meegenomen en hoe toegang mogelijk is. Voor terugkerende reiniging kunt u de gewenste frequentie aangeven. De uiteindelijke werkwijze en planning volgen uit het overleg over uw locatie.',
 faq=[('Kunnen jullie ook hogere ramen reinigen?','Dat hangt af van hoogte, bereikbaarheid en de situatie rond het pand. Geef deze kenmerken door, zodat een geschikte en veilige aanpak kan worden beoordeeld.'),('Kan ik een eenmalige afspraak aanvragen?','Ja. U kunt een eenmalige reiniging of terugkerende glasbewassing bespreken. Vermeld in beide gevallen welk glas u wilt laten reinigen.'),('Zijn kozijnen standaard inbegrepen?','Maak bij uw aanvraag duidelijk of u ook kozijnen, omlijstingen of andere onderdelen wilt laten reinigen. Welke werkzaamheden worden meegenomen, hoort in de afgesproken scope.')]),
 dict(slug='horecaschoonmaak', group='schoonmaak', name='Horecaschoonmaak', headline='Achter de schermen. Tot in de details.', image='schoonmaak-keuken.webp',
 short='Van publieksruimte tot keuken en sanitair. Een schoonmaakvraag die aansluit op het ritme van uw horecalocatie.',
 intro='In de horeca volgen voorbereiding, ontvangst en afsluiting elkaar snel op. Juist daarom helpt een duidelijk schoonmaakplan: welke ruimte is op welk moment vrij en welke werkzaamheden moeten gereed zijn voordat de volgende gasten komen? Veele Services biedt schoonmaak voor horecalocaties in Den Haag en de Randstad.',
 second='Een restaurantzaal, keuken en toiletgroep vragen ieder om een eigen afbakening. Geef aan of u terugkerende schoonmaak zoekt, een grondige eenmalige reiniging wilt bespreken of extra aandacht nodig heeft rond een evenement. Daarmee kan de aanvraag beter worden afgestemd op uw bedrijfsvoering.',
 scope=[('Publieksruimte en entree','Bespreek vloeren, looproutes, tafels en overige oppervlakken die bij de schoonmaak horen. Benoem materialen of delen van de inrichting waarvoor speciale gebruiksinstructies gelden.'),('Keuken en werkruimtes','Omschrijf welke oppervlakken, apparatuur of afzuiging u wilt laten beoordelen. Werkzaamheden aan specifieke apparatuur moeten uitdrukkelijk worden besproken en behoren niet vanzelfsprekend tot elke opdracht.'),('Sanitaire ruimtes','Denk aan toiletten, wastafels, spiegels, vloeren en contactpunten. Tijdens een bijeenkomst kan aanvullend sanitaironderhoud een aparte aanvraag zijn.')],
 checklist=['Soort horecalocatie en openingstijden','Ruimtes en gewenste werkzaamheden','Beschikbare tijd tussen afsluiting en opening','Reguliere schoonmaak of eenmalige reiniging'],
 planning='Zet de gewenste werkzaamheden naast uw openings- en voorbereidingstijden. Noteer welke ruimtes tegelijk beschikbaar zijn en wie vooraf zaken vrijmaakt. Zo wordt duidelijk wat binnen het beschikbare tijdvenster besproken moet worden.',
 faq=[('Kan alleen de keuken worden aangevraagd?','Ja. Omschrijf de keuken, de te reinigen onderdelen en de gewenste planning. De precieze werkzaamheden en mogelijkheden worden daarna besproken.'),('Is schoonmaak tijdens een evenement mogelijk?','U kunt toiletschoonmaak en praktische ondersteuning tijdens een evenement aanvragen. Vermeld drukke momenten, bezoekersaantallen en de gewenste aanwezigheid.'),('Is schoonmaak hetzelfde als een voedselveiligheidscontrole?','Nee. Schoonmaak betreft de afgesproken reinigingswerkzaamheden. De verantwoordelijkheden en controles binnen uw eigen bedrijfsvoering blijven afzonderlijke onderwerpen.')]),
 dict(slug='opleveringsschoonmaak', group='schoonmaak', name='Opleveringsschoonmaak', headline='Een nieuwe start. Een verzorgde overdracht.', image='schoonmaak-afzuigkap.webp',
 short='Een woning of kantoor klaar voor een volgend hoofdstuk. Bespreek de schoonmaak rond verhuizing of oplevering.',
 intro='Bij een verhuizing of oplevering komen veel werkzaamheden samen. Een duidelijke schoonmaakafspraak helpt om de overgang overzichtelijk te houden. Veele Services biedt schoonmaak van woningen en kantoren; ook een aanvraag rond een verhuizing of oplevering is mogelijk.',
 second='De staat van de locatie is belangrijk. Is het pand leeg of nog ingericht? Zijn andere werkzaamheden afgerond? En welke onderdelen moeten gereinigd zijn bij de overdracht? Door dit vooraf te beschrijven kan de gewenste schoonmaak gericht worden besproken, zonder onduidelijkheid over wat wel en niet bij de opdracht hoort.',
 scope=[('Een woning na verhuizing','Bespreek keuken, sanitair, vloeren en andere ruimtes die aandacht nodig hebben. Geef ook aan welke kasten, meubels of apparaten achterblijven en of die onderdeel van de aanvraag zijn.'),('Een kantoor bij overdracht','Een kantooroplevering kan verschillende verdiepingen en gedeelde voorzieningen omvatten. Leg per ruimte vast wat nodig is en wanneer deze toegankelijk wordt.'),('Aanvullende werkzaamheden','Ontruiming of herstelwerk is een ander onderdeel dan schoonmaak. Als u dit wilt bespreken, benoem het afzonderlijk zodat de aanvraag de juiste omvang krijgt.')],
 checklist=['Woning of kantoor en geschatte omvang','Leeg, gedeeltelijk ingericht of in gebruik','Gewenste datum en overdrachtsmoment','Ruimtes en aanvullende wensen'],
 planning='Plan de gewenste schoonmaak zo dat de ruimtes beschikbaar zijn. Een harde overdrachtsdatum is nuttige informatie, maar een aanvraag is nog geen bevestigde afspraak. Bespreek ook wat er gebeurt als andere werkzaamheden uitlopen.',
 faq=[('Kan ik een gewenste einddatum opgeven?','Ja. Geef zowel het gewenste schoonmaakmoment als de overdrachtsdatum door. De haalbaarheid wordt besproken voordat afspraken worden gemaakt.'),('Wordt een pand ook ontruimd?','Ontruiming moet apart worden aangevraagd en besproken. Vermeld welke spullen of materialen aanwezig zijn; neem niet aan dat afvoer automatisch bij schoonmaak hoort.'),('Wat als de omvang nog niet bekend is?','Een eerste beschrijving van het pand en de ruimtes is voldoende om het gesprek te beginnen. Geef aan welke informatie nog ontbreekt.')]),
 dict(slug='objectbeveiliging', group='beveiliging', name='Objectbeveiliging', headline='Aandacht voor uw pand. Oog voor wat er gebeurt.', image='beveiliging-waterman.webp',
 short='Toegangscontrole, toezicht en controlerondes voor uw kantoor, winkel, magazijn of terrein.',
 intro='Wie komt uw locatie binnen, welke ruimtes vragen aandacht en wat moet er gebeuren bij een afwijkende situatie? Dat zijn concrete vragen achter objectbeveiliging. Veele Services biedt beveiliging van panden en terreinen in Den Haag en de Randstad.',
 second='De passende inzet hangt samen met het gebruik van het object. Een kantoor met bezoekers aan de balie heeft een andere vraag dan een terrein buiten openingstijden. Beschrijf daarom de gewenste aanwezigheid, de belangrijkste taken en de momenten waarop toezicht nodig is.',
 scope=[('Toegang en ontvangst','Bespreek de controle van bezoekers en leveranciers, registratie en afspraken voor toelating. Een gastvrije ontvangst kan samengaan met duidelijke toegangsregels.'),('Rondes en observatie','Controlerondes kunnen gericht zijn op afgesproken ruimtes, deuren, poorten en zichtbare onregelmatigheden. De aandachtspunten worden gekoppeld aan uw locatie.'),('Afspraken bij bijzonderheden','Leg vast wie bereikbaar is, wanneer overleg nodig is en hoe bevindingen worden gedeeld. De gewenste opvolging hoort bij de voorbereiding van de opdracht.')],
 checklist=['Type locatie en globale indeling','Benodigde dagen en tijdvensters','Toezichts- en ontvangsttaken','Contactpersoon voor verdere afstemming'],
 planning='Begin met de vraag of doorlopende aanwezigheid nodig is of dat controles op afgesproken momenten kunnen passen. Deel via de openbare aanvraag alleen een globale omschrijving. Sleutel-, alarm- en toegangsinformatie bespreekt u later rechtstreeks.',
 faq=[('Wat is het verschil met mobiele surveillance?','Bij objectbeveiliging bespreekt u toezicht voor een specifieke locatie. Mobiele surveillance draait om periodieke controlerondes. De gewenste aanwezigheid en taken bepalen welke vorm past.'),('Kunnen receptietaken worden gecombineerd?','Dat is bespreekbaar. Geef aan welke ontvangst-, registratie- en toezichtstaken u wilt combineren en op welke momenten.'),('Moet ik beveiligingsdetails in de aanvraag zetten?','Een globale omschrijving is voldoende. Deel geen alarmcodes, toegangscodes of gevoelige instructies via het openbare formulier.')]),
 dict(slug='mobiele-surveillance', group='beveiliging', name='Mobiele surveillance', headline='Controle op locatie. Op afgesproken momenten.', image='bedrijfsbus.webp',
 short='Periodieke controlerondes bij uw pand of terrein, afgestemd op de aandachtspunten van uw locatie.',
 intro='Niet iedere locatie vraagt om voortdurende aanwezigheid. Soms ligt de behoefte bij een controle tijdens afgesproken tijdvensters of buiten de normale openingstijden. Veele Services biedt mobiele surveillance voor panden en terreinen in Den Haag en de Randstad.',
 second='Een controleronde krijgt pas betekenis als duidelijk is waar op gelet moet worden. Denk aan de afsluiting van het gebouw, de staat van ramen en deuren of opvallende situaties op een terrein. Bespreek ook wie bij bijzonderheden moet worden geïnformeerd.',
 scope=[('Controle van het gebouw','Ramen, deuren en poorten kunnen onderdeel zijn van de afgesproken ronde. Vermeld in een eerste gesprek welke zones extra aandacht vragen.'),('Rondom het terrein','Bespreek de gewenste observaties rond het pand, zoals zichtbare schade of ongewenste aanwezigheid. De opdracht bepaalt welke controles worden uitgevoerd.'),('Bevindingen en contact','De officiële dienstverlening noemt digitale rapportage van rondes. Bespreek welke informatie u nodig heeft, wie de ontvanger is en welke contactafspraken gelden.')],
 checklist=['Pand of terrein en plaats','Gewenste controleperioden','Globale aandachtspunten','Wensen voor contact en terugkoppeling'],
 planning='Maak onderscheid tussen een ronde en doorlopende bewaking. Beschrijf de gewenste frequentie en tijdvensters, maar houd gevoelige toegangsinformatie buiten de openbare aanvraag. De praktische inrichting van de rondes volgt uit het gesprek.',
 faq=[('Is er dan continu iemand op locatie?','Nee, mobiele surveillance bestaat uit controlerondes. Als u doorlopende aanwezigheid zoekt, bespreek dan objectbeveiliging.'),('Kunnen opening en afsluiting worden besproken?','Geef de gewenste taken en tijden aan. Welke openings- of afsluitwerkzaamheden onderdeel worden van de inzet, wordt vooraf afgestemd.'),('Is dit een garantie op directe aanwezigheid?','Nee. Een ronde en eventuele aanvullende opvolging moeten concreet worden afgesproken. Vermeld uw verwachtingen zodat hierover geen onduidelijkheid bestaat.')]),
 dict(slug='evenementenbeveiliging', group='beveiliging', name='Evenementenbeveiliging', headline='Een goed evenement. Begint bij de ontvangst.', image='beveiliging-evenement.webp',
 short='Toegang, bezoekersstromen en toezicht. Een beveiligingsaanvraag die past bij uw programma en publiek.',
 intro='Een evenement brengt bezoekers, leveranciers en medewerkers samen op één locatie. Bij de ingang, tijdens het programma en bij vertrek zijn de aandachtspunten anders. Veele Services biedt evenementenbeveiliging in Den Haag en de Randstad.',
 second='Voor een eerste gesprek zijn de datum, locatie, openingstijden en het verwachte aantal bezoekers nuttig. Omschrijf daarnaast wat voor evenement u organiseert en hoe het programma verloopt. Zo kan de gewenste inzet worden besproken in samenhang met het geheel.',
 scope=[('Toegang en ticketcontrole','Bespreek de ingangen, toegangsbewijzen en ontvangst van bezoekers. Maak duidelijk welke controles gewenst zijn en wie vanuit de organisatie beslissingen neemt.'),('Toezicht tijdens het programma','Verschillende momenten kunnen om verschillende inzet vragen. Denk aan aankomst, pauzes en vertrek. Geef piekmomenten en bijzonderheden van de locatie door.'),('Afstemming met de organisatie','Beveiliging staat naast andere werkzaamheden, zoals gastontvangst, bardiensten en schoonmaak. Duidelijke taken en contactpersonen helpen bij een samenhangende voorbereiding.')],
 checklist=['Datum, locatie en programma','Verwacht bezoekersaantal','Opening, publieksmomenten en afsluiting','Gewenste beveiligings- en ontvangsttaken'],
 planning='Omschrijf eerst het evenement en vervolgens de taken waarvoor u ondersteuning zoekt. Vermeld ook voorbereiding en afronding wanneer daarvoor inzet nodig is. De gewenste aantallen medewerkers zijn een gesprekspunt, geen automatisch berekende uitkomst.',
 faq=[('Hoeveel beveiligers heb ik nodig?','Dat is afhankelijk van onder meer locatie, publiek, programma en de gestelde eisen. Geef de kenmerken van het evenement door om passende inzet te bespreken.'),('Kunnen bar en schoonmaak ook worden aangevraagd?','Ja. U kunt meerdere diensten in één aanvraag opnemen. De werkzaamheden en planning worden per onderdeel besproken.'),('Is een aanvraag meteen een reservering?','Nee. De aanvraag brengt uw wensen in beeld. Beschikbaarheid, inzet en definitieve afspraken moeten worden bevestigd.')]),
 dict(slug='receptiediensten', group='beveiliging', name='Receptiediensten', headline='Een warm welkom. Een helder aanspreekpunt.', image='portret.webp',
 short='Ondersteuning bij bezoekersontvangst, registratie, telefoon en praktische taken aan de receptie.',
 intro='De receptie is vaak het eerste persoonlijke contact met uw organisatie. Bezoekers willen weten waar ze moeten zijn, telefoontjes komen binnen en leveranciers melden zich. Veele Services biedt receptiediensten waarbij ontvangst en aandacht voor toegang samen kunnen komen.',
 second='De juiste invulling hangt af van uw gebouw. Een balie met veel bezoekers vraagt om andere afspraken dan tijdelijke bezetting tijdens afwezigheid. Maak daarom duidelijk welke taken u wilt overdragen en welke bevoegdheden bij uw eigen medewerkers blijven.',
 scope=[('Bezoekers ontvangen','Denk aan aanmelden, registreren en doorverwijzen. Bespreek hoe bezoekers worden aangekondigd en wie toegang kan verlenen.'),('Telefoon, post en overleg','Telefonische beantwoording, post- en pakketverwerking en ondersteuning rond vergaderruimtes behoren tot de gepubliceerde mogelijkheden. Selecteer de taken die voor uw balie relevant zijn.'),('Toegang met duidelijke afspraken','Wanneer ontvangst wordt gecombineerd met toezicht, zijn goede instructies belangrijk. Bespreek de rolverdeling en welke bijzonderheden direct moeten worden gemeld.')],
 checklist=['Gewenste dagen en bezettingstijden','Bezoekersaantallen en balietaken','Structurele of tijdelijke ondersteuning','Aanspreekpunt voor instructie en afstemming'],
 planning='Maak een overzicht van een normale werkdag aan de balie: bezoekers, telefoontjes, leveringen en vergaderingen. Dit helpt om de gewenste inzet concreet te maken. Deel toegangsgegevens pas via de later afgesproken route.',
 faq=[('Is tijdelijke bezetting mogelijk?','Tijdelijke en structurele receptieondersteuning zijn bespreekbaar. Geef de periode en het aantal uren aan, zodat de mogelijkheden kunnen worden beoordeeld.'),('Kunnen telefoon en post worden meegenomen?','Ja, deze taken worden genoemd in het aanbod. Beschrijf welke werkzaamheden u precies zoekt en op welke tijden.'),('Kan receptie samen met beveiliging?','Dat kan worden besproken. Taken, rolverdeling en benodigde inzet moeten vooraf duidelijk zijn; ontvangst en beveiliging zijn niet automatisch dezelfde opdracht.')]),
 dict(slug='evenementenondersteuning', group='facilitair', name='Evenementenondersteuning', headline='Van eerste opbouw. Tot laatste gast.', image='beveiliging-evenement.webp',
 short='Praktische ondersteuning voor opbouw, ontvangst, catering en afronding van uw bijeenkomst.',
 intro='Bij een evenement gaat veel werk schuil achter een prettige bezoekerservaring. Materialen moeten op hun plek staan, gasten zoeken hun weg en na afloop moet de locatie worden afgerond. Veele Services biedt facilitaire medewerkers voor praktische werkzaamheden rond evenementen.',
 second='De meest bruikbare aanvraag volgt het programma. Welke taken liggen vóór opening, wat gebeurt tijdens de bijeenkomst en waar is na afloop ondersteuning nodig? Met die indeling wordt ook zichtbaar of meerdere diensten op dezelfde locatie gecombineerd kunnen worden.',
 scope=[('Vooraf: op- en voorbereiden','Geef aan welke praktische opbouwtaken u wilt bespreken en wanneer de locatie toegankelijk is. Omschrijf materialen en werkzaamheden zonder technische taken automatisch mee te rekenen.'),('Tijdens: gasten en ondersteuning','Gastontvangst, begeleiding en cateringondersteuning kunnen deel uitmaken van de aanvraag. Benoem de rol van uw eigen organisatie en wie aanwijzingen geeft.'),('Na afloop: afronden','Afbouw en schoonmaak zijn verschillende werkzaamheden. Vermeld wat u nodig heeft en op welk moment, zodat de gewenste inzet per onderdeel duidelijk is.')],
 checklist=['Programma inclusief op- en afbouw','Concrete taken per tijdvak','Locatie en verwacht aantal gasten','Combinaties met bar, schoonmaak of beveiliging'],
 planning='Verdeel het evenement in voorbereiding, uitvoering en afronding. Geef per fase de taken en tijdvensters door. Zo kan de inzet beter worden besproken dan met alleen een totaal aantal uren of medewerkers.',
 faq=[('Kan ik hulp voor alleen de opbouw aanvragen?','Ja. U kunt een afgebakende taak of ondersteuning voor verschillende fases bespreken. Geef duidelijk aan welke werkzaamheden u bedoelt.'),('Is technische productie inbegrepen?','Neem dat niet automatisch aan. Geluid, licht, constructies en andere technische werkzaamheden hebben een eigen scope. Beschrijf uw wensen om de mogelijkheden te bespreken.'),('Kunnen meerdere diensten samen?','Ja, de aanvraaghulp ondersteunt een combinatie. U kunt facilitaire inzet, schoonmaak en beveiliging in één overzicht verzamelen.')]),
 dict(slug='bardiensten', group='facilitair', name='Bardiensten', headline='Goed ontvangen. Vriendelijk geholpen.', image='bedrijfsbus-detail.webp',
 short='Barmedewerkers voor uw bijeenkomst of evenement. Bespreek de bezetting, taken en drukke momenten.',
 intro='Een bar is een ontmoetingsplek én een werkplek waar het tempo kan wisselen. Tijdens binnenkomst, een pauze of de afsluiting komen vragen soms tegelijk. Veele Services biedt bardiensten voor bijeenkomsten en evenementen.',
 second='Voor passende ondersteuning helpt het om het barconcept concreet te maken. Hoe wordt besteld, hoe wordt afgerekend en welke voorbereiding hoort bij de opdracht? Geef ook aan of u alleen bezetting tijdens het programma zoekt of ondersteuning voor opening en na afloop.',
 scope=[('Service aan de bar','Omschrijf de gewenste werkzaamheden en het soort bijeenkomst. Het verwachte aantal gasten en de programma-indeling zijn nuttig om de inzet te bespreken.'),('Voorbereiding en afronding','Een bar openen en netjes achterlaten kan extra tijd vragen. Geef aan welke voorbereidende en afsluitende taken u wilt laten uitvoeren.'),('Samenwerking op locatie','Maak duidelijk wie verantwoordelijk is voor voorraad, materialen en instructies. Personele ondersteuning betekent niet automatisch dat producten of apparatuur worden geleverd.')],
 checklist=['Type bijeenkomst en aantal gasten','Openingstijden en piekmomenten','Taken voor, tijdens en na het programma','Werkwijze voor bestelling en afrekening'],
 planning='Zet verwachte drukte af tegen het programma en beschrijf wat al door uw eigen team wordt gedaan. Dat geeft een concreet startpunt voor het gesprek over aanvullende barondersteuning.',
 faq=[('Leveren jullie ook drank en barapparatuur?','De aanvraag gaat over bardiensten. Vermeld aanvullende wensen apart en bespreek wie producten, voorraad en apparatuur regelt.'),('Kan ik een geschat bezoekersaantal doorgeven?','Ja. Geef een realistische schatting en benoem piekmomenten. Dat helpt bij het overleg over inzet, zonder dat het automatisch een personeelsberekening vormt.'),('Kan toiletschoonmaak erbij?','Ja. U kunt beide diensten in dezelfde aanvraag opnemen. Vermeld de tijden en de sanitaire voorzieningen, zodat elk onderdeel apart kan worden besproken.')]),
 dict(slug='toiletschoonmaak', group='facilitair', name='Toiletschoonmaak', headline='Een klein detail. Een groot verschil.', image='schoonmaak-keuken.webp',
 short='Aandacht voor sanitair tijdens drukke momenten in de horeca of op uw evenement.',
 intro='Verzorgd sanitair hoort bij een prettige ontvangst. Tijdens een evenement of drukke horecadienst worden toiletten, wastafels en contactpunten intensief gebruikt. Veele Services biedt toiletschoonmaak als onderdeel van facilitaire ondersteuning.',
 second='Een passende aanvraag gaat niet alleen over het aantal toiletten. Ook de duur, het verwachte gebruik en de verdeling van bezoekers over het programma spelen mee. Geef aan of u onderhoud tijdens opening, een reiniging na afloop of een combinatie wilt bespreken.',
 scope=[('Reiniging van sanitaire ruimtes','Denk aan toiletten, wastafels, spiegels, vloeren en veelgebruikte contactpunten. Maak duidelijk welke ruimtes bij de opdracht horen.'),('Aandacht tijdens het programma','Bij een langer evenement kunt u terugkerende schoonmaakrondes bespreken. Pieken tijdens pauzes of programmawisselingen zijn nuttige informatie.'),('Voorzieningen en werkafspraken','Bespreek wie verbruiksartikelen beschikbaar stelt en welke controles gewenst zijn. Maak ook duidelijk bij wie bijzonderheden of defecten moeten worden gemeld.')],
 checklist=['Aantal toiletgroepen en voorzieningen','Verwacht gebruik en bezoekersaantal','Openingstijden en gewenste rondes','Afspraken over materiaal en aanvulling'],
 planning='Kijk naar het sanitair als onderdeel van het bezoekersverloop. Vermeld drukke momenten en de gewenste afronding na het evenement. De frequentie en concrete werkzaamheden worden op uw aanvraag afgestemd.',
 faq=[('Is dit ook mogelijk tijdens een evenement?','Ja, toiletschoonmaak tijdens horeca- en evenementendrukte behoort tot het aanbod. Geef duur, voorzieningen en verwachte bezoekers door.'),('Worden toiletpapier en zeep geleverd?','Bespreek wie de verbruiksartikelen levert en welke aanvulwerkzaamheden gewenst zijn. Dit hoort bij de afspraken en is niet automatisch inbegrepen.'),('Kan alleen een eindschoonmaak worden aangevraagd?','Ja. Vermeld dat u schoonmaak na afloop zoekt en wanneer de sanitaire ruimtes beschikbaar zijn. De mogelijkheden en planning worden besproken.')]),
]

AREAS = [
 dict(slug='den-haag', name='Den Haag', focus='Verschillende diensten. Eén samenhangende vraag.', intro='Veele Services heeft zijn thuisbasis in Duindorp, Den Haag. Vanuit die Haagse basis bieden we schoonmaak, beveiliging en facilitaire ondersteuning voor bedrijven, VvE’s, horeca en evenementen. Van een gedeeld trappenhuis tot een kantoor met bezoekers: uw locatie en het gebruik ervan vormen het vertrekpunt.',
 detail='Een Haags pand kan meerdere functies hebben. Op de begane grond ontvangt u gasten, boven wordt gewerkt of gewoond en achter de schermen zijn gezamenlijke voorzieningen. Door die functies apart te benoemen wordt duidelijk waar schoonmaak nodig is en waar ontvangst of toezicht een rol kan spelen.',
 contexts=[('Kantoor, winkel en ontvangst','Vertel welke ruimtes dagelijks worden gebruikt, wanneer bezoekers komen en op welke momenten onderhoud mogelijk is. Schoonmaak en receptie kunnen in hetzelfde gesprek worden besproken.'),('VvE en woongebouw','Voor een portiek of appartementencomplex helpt een lijst met entrees, liften, gangen en gedeelde voorzieningen. Benoem de contactpersoon van bestuur of beheerder.'),('Horeca en bijeenkomsten','In Scheveningen, het Statenkwartier, Ypenburg en andere delen van Den Haag kunt u uw locatie bespreken. Geef openingstijden en publieksmomenten aan voor een gerichte aanvraag.')],
 ask='Wilt u meerdere diensten voor één adres? Beschrijf dan per dienst de gewenste taken. Vermeld ook welke momenten elkaar overlappen en wie op locatie de afspraken afstemt.', related=['kantoorschoonmaak','vve-schoonmaak','objectbeveiliging'], question='Werken jullie in heel Den Haag?', answer='U kunt locaties in heel Den Haag bespreken. De concrete werkzaamheden, bereikbaarheid en planning worden per aanvraag afgestemd. Vermeld uw wijk en het soort pand om het gesprek gericht te beginnen.'),
 dict(slug='scheveningen', name='Scheveningen', focus='Een verzorgde locatie. Rond het ritme van uw gasten.', intro='Scheveningen is onderdeel van Den Haag en ligt dicht bij de Haagse thuisbasis van Veele Services. Voor een horecalocatie, woning, kantoor of VvE kunt u schoonmaak en aanvullende ondersteuning bespreken. Begin bij de momenten waarop uw locatie wordt gebruikt en wanneer werkzaamheden praktisch kunnen plaatsvinden.',
 detail='Bij een horecalocatie volgen voorbereiding, ontvangst en afsluiting elkaar op. De keuken kan nog in gebruik zijn terwijl andere ruimtes al beschikbaar zijn. Door per ruimte een tijdvenster te benoemen, maakt u de aanvraag concreter. Ook voor een woongebouw helpt het om gezamenlijke ruimtes en bereikbaarheid apart te beschrijven.',
 contexts=[('Horecaschoonmaak','Bespreek keuken, publieksruimte en sanitair als afzonderlijke onderdelen. Geef aan of u een eenmalige reiniging of terugkerende schoonmaak zoekt.'),('Glas en gezamenlijke ruimtes','Voor woningen en VvE’s zijn de bereikbaarheid van glas en de toegang tot gemeenschappelijke ruimtes belangrijke gesprekspunten. Benoem de verdiepingen en eventuele obstakels.'),('Ondersteuning rond een bijeenkomst','Zoekt u extra barondersteuning of sanitaironderhoud? Geef programma, openingstijden en bezoekersaantallen door om de mogelijkheden te bespreken.')],
 ask='Noteer wanneer elke ruimte beschikbaar is, wie toegang geeft en welke taken vóór ontvangst van gasten gereed moeten zijn. Zo kan de gewenste inzet worden besproken zonder uw dagelijkse werkzaamheden uit het oog te verliezen.', related=['horecaschoonmaak','glasbewassing','toiletschoonmaak'], question='Kunnen schoonmaak en sanitaironderhoud samen?', answer='Ja. U kunt reguliere schoonmaak en extra sanitaironderhoud in één aanvraag bespreken. Benoem de ruimtes en momenten afzonderlijk; het zijn verschillende onderdelen van de gewenste inzet.'),
 dict(slug='delft', name='Delft', focus='Duidelijke afspraken. Voor uw gedeelde ruimtes.', intro='Veele Services noemt Delft als onderdeel van het werkgebied in de Randstad. U kunt schoonmaak, beveiliging en facilitaire ondersteuning voor uw locatie aanvragen. Voor een VvE of beheerder begint een bruikbaar schoonmaakplan met een helder overzicht van de gezamenlijke ruimtes.',
 detail='Bij een woongebouw is niet elke ruimte hetzelfde. Een entree wordt anders gebruikt dan een fietsenstalling en een lift heeft andere aandachtspunten dan een open galerij. Beschrijf daarom per onderdeel de gewenste werkzaamheden. Dit maakt het gemakkelijker om frequentie, toegang en extra onderhoud te bespreken.',
 contexts=[('Portieken en appartementen','Maak een overzicht van entrees, gangen, trappen en liften. Geef aan welke delen gezamenlijk zijn en wie namens de VvE over de opdracht beslist.'),('Periodieke onderhoudsmomenten','Glasbewassing en vloerreiniging kunnen naast de reguliere schoonmaak worden besproken. Vermeld welke delen van het complex hiervoor in aanmerking komen.'),('Ook voor uw bedrijfslocatie','Heeft u een kantoor, winkel of evenement in Delft? Geef de functie van de locatie, de gewenste dienstverlening en de planning door voor een passende aanvraag.')],
 ask='Bij meerdere gebouwen is een lijst per adres handig. Noteer aantal verdiepingen, voorzieningen en toegangsmomenten. Zo voorkomt u dat de wensen voor het ene gebouw onbedoeld ook voor het andere worden aangenomen.', related=['vve-schoonmaak','glasbewassing','kantoorschoonmaak'], question='Kunnen meerdere VvE-adressen in Delft worden besproken?', answer='Ja. Beschrijf per adres de ruimtes en werkzaamheden. Geef ook aan of dezelfde contactpersoon en frequentie gelden of dat hierover per gebouw afspraken nodig zijn.'),
 dict(slug='zoetermeer', name='Zoetermeer', focus='Een schoon kantoor. Op een werkbaar moment.', intro='Zoetermeer behoort tot het werkgebied dat Veele Services voor de Randstad noemt. Voor kantoren, winkels, woongebouwen en evenementen kunt u schoonmaak, beveiliging en facilitaire ondersteuning bespreken. Bij een kantoor begint de planning met het werkrooster en het dagelijks gebruik van de ruimtes.',
 detail='Een vergaderruimte die enkele keren wordt gebruikt heeft een andere schoonmaakvraag dan een drukke pantry. Door de bezetting en gebruiksmomenten te beschrijven, krijgt uw aanvraag meer inhoud dan alleen een oppervlakte. Geef ook aan welke werkzaamheden regelmatig terugkeren en waar af en toe extra aandacht nodig is.',
 contexts=[('Werkplekken en overleg','Benoem werkvloeren, vergaderruimtes en ontvangstzones. Geef de gebruikstijden aan, zodat schoonmaakmomenten met de bedrijfsvoering kunnen worden besproken.'),('Sanitair en pantry','Het aantal gebruikers en de drukte helpen bij de afstemming van de gewenste frequentie. Maak duidelijk welke voorzieningen bij de opdracht horen.'),('Ontvangst of beveiliging erbij','Zoekt u naast schoonmaak ook ondersteuning aan de receptie of toezicht op het pand? Breng de taken samen in één aanvraag, met een planning per dienst.')],
 ask='Maak een eenvoudig overzicht van de werkdagen, aanwezige medewerkers en bereikbare ruimtes. Benoem incidentele momenten, zoals een verhuizing of extra bijeenkomst, apart van de terugkerende schoonmaakvraag.', related=['kantoorschoonmaak','receptiediensten','objectbeveiliging'], question='Kan de planning aansluiten op wisselende kantoordagen?', answer='Geef uw werkrooster en de verschillen tussen dagen door. De gewenste frequentie en uitvoermomenten kunnen daarmee worden besproken; definitieve tijden worden vooraf afgesproken.'),
 dict(slug='leiden', name='Leiden', focus='Heldere ramen. Een zorgvuldig voorbereide aanpak.', intro='Veele Services biedt dienstverlening in de Randstad en noemt Leiden expliciet als werkgebied. Voor een bedrijfspand, woning of VvE kunt u glasbewassing en schoonmaak aanvragen. Ook beveiliging en facilitaire ondersteuning zijn bespreekbaar voor uw locatie.',
 detail='Bij glasbewassing is de bereikbaarheid van het gebouw net zo relevant als het aantal ramen. De binnen- en buitenzijde kunnen verschillende toegang vragen. Door per gevel of verdieping te beschrijven wat u wilt laten reinigen, kan de aanpak gericht worden beoordeeld.',
 contexts=[('Glas van uw bedrijfspand','Vermeld verdiepingen, binnen- of buitenzijde en tijden waarop ruimtes beschikbaar zijn. Geef ook aan of het om een eenmalige of terugkerende aanvraag gaat.'),('Gezamenlijk glas van een VvE','Maak onderscheid tussen glas in gedeelde ruimtes en ramen van individuele woningen. Zo is de omvang van de aanvraag duidelijk voor bestuur en beheerder.'),('Schoonmaak in combinatie','U kunt glasbewassing bespreken naast kantoorschoonmaak of onderhoud van het wooncomplex. Geef aan welke werkzaamheden u in dezelfde planning wilt meenemen.')],
 ask='Noteer mogelijke obstakels, de route naar de ramen en het gebruik van de ruimtes. Er is geen universele aanpak voor ieder pand; de methode moet bij het gebouw en de bereikbaarheid passen.', related=['glasbewassing','vve-schoonmaak','kantoorschoonmaak'], question='Wat moet ik doorgeven voor glasbewassing in Leiden?', answer='Vermeld type pand, verdiepingen, gewenste glaspartijen en bereikbaarheid. Geef aan of binnen- en buitenzijde moeten worden gereinigd en welke planning u voor ogen heeft.'),
 dict(slug='rotterdam', name='Rotterdam', focus='De juiste aanwezigheid. Bij uw beveiligingsvraag.', intro='Rotterdam is onderdeel van het gepubliceerde werkgebied van Veele Services. U kunt beveiliging, schoonmaak en facilitaire ondersteuning bespreken voor uw pand, bedrijf of evenement. Voor beveiliging is de eerste vraag vaak: zoekt u doorlopend toezicht of controle op afgesproken momenten?',
 detail='Een locatie met bezoekers heeft andere aandachtspunten dan een afgesloten pand buiten openingstijden. Beschrijf daarom wanneer mensen aanwezig zijn en welke taken u verwacht. Objectbeveiliging, mobiele surveillance en receptiediensten hebben elk hun eigen invulling; de gewenste situatie bepaalt het gesprek.',
 contexts=[('Toezicht op een object','Benoem de locatie, de benodigde tijdvensters en taken zoals toegang of controlerondes. Deel gevoelige instructies pas later rechtstreeks.'),('Periodieke controles','Mobiele surveillance draait om rondes en afgesproken aandachtspunten. Geef aan welke momenten belangrijk zijn en welke terugkoppeling u wenst.'),('Ontvangst en evenementen','Voor receptie of een evenement zijn bezoekersaantallen, openingstijden en programma nuttig. Bar, schoonmaak en facilitaire hulp kunnen als aanvullende wensen worden besproken.')],
 ask='Beschrijf de gewenste aanwezigheid in gewone taal. Zet erbij wie bij bijzonderheden bereikbaar moet zijn en welke informatie u achteraf nodig heeft. Deel geen alarm- of toegangscodes in de openbare aanvraag.', related=['objectbeveiliging','mobiele-surveillance','evenementenbeveiliging'], question='Kan ik toezicht en rondes laten vergelijken?', answer='Ja. Beschrijf de situatie en de momenten waarop u controle zoekt. In het gesprek kan worden bekeken welke vorm van aanwezigheid aansluit op uw vraag. Een aanvraag bevat nog geen bevestigde inzet.'),
]

